              "value": "72",
              "value_kind": "scalar",
              "unit": "s",
              "condition": "forward_cuda_graph vs 실시간 멀티스트림 forward_cuda_graph",
              "element_ids": [
                "p60:e467",
                "p60:enh:e9",
                "p60:enh:e10"
